async function sendEmail(mail: any) {
  return new Promise<any>((resolve, reject) =>{
    nodemailerTransporter.sendMail(mail, (error, info) => {
        if (error) {
          console.error(error);
          reject({})
        }
        console.log('Message %s sent: %s', info.messageId, info.response);
        resolve({})
      });
  })
}
